window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[130]={"id":"130","numero":130,"titre":"Personne âgée malade","objectifs":[{"id":"130-1","rang":"A","rubrique":"Définition","titre":"Connaître la prise en charge globale du sujet âgé","contenu":"<p>La prise en charge du sujet âgé malade repose sur une <span class=\"kw-def\">approche globale et pluridisciplinaire</span>, fondée sur le <span class=\"kw-def\">raisonnement gériatrique « 1 + 2 + 3 »</span> et sur l'<span class=\"kw-def\">évaluation gériatrique standardisée (EGS)</span>.</p>\n      <p><strong>Démarche structurée et hiérarchisée</strong></p>\n      <ul>\n        <li><strong>1.</strong> Rechercher et corriger le <span class=\"kw-etio\">facteur précipitant</span> = <strong>priorité</strong> (le plus souvent <span class=\"kw-clinique\">réversible</span>).</li>\n        <li><strong>2.</strong> Faire le bilan de la <span class=\"kw-etio\">maladie chronique</span> et réévaluer le <span class=\"kw-ttt\">traitement de fond</span> (traquer l'<span class=\"kw-alerte\">iatrogénie</span> +++).</li>\n        <li><strong>3.</strong> Instaurer des mesures améliorant <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">conséquences du vieillissement</span>.</li>\n      </ul>\n      <p>S'y ajoutent en amont la <span class=\"kw-clinique\">détection des situations de vulnérabilité</span> et le <span class=\"kw-clinique\">repérage de la polypathologie</span>.</p>\n      <div class=\"callout callout-info\">\n        <strong>Équipe pluridisciplinaire</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Gériatre</span></li>\n          <li><span class=\"kw-clinique\">IDE</span></li>\n          <li><span class=\"kw-clinique\">Assistante sociale</span></li>\n          <li><span class=\"kw-clinique\">Ergothérapeute</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 123 — Vieillissement normal · 133 — Autonomie-dépendance du sujet âgé · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"130-2","rang":"B","rubrique":"Définition","titre":"Connaître l'évaluation gériatrique standardisée","contenu":"<p>L'<span class=\"kw-def\"><strong>évaluation gériatrique standardisée (EGS)</strong></span> est une <span class=\"kw-def\">évaluation multidimensionnelle et standardisée</span> du sujet âgé.</p>\n      <div class=\"callout callout-info\">\n        <strong>Conditions de réalisation</strong>\n        <ul>\n          <li>Réalisée au mieux <span class=\"kw-clinique\">en dehors d'une situation aiguë</span>, chez un patient <span class=\"kw-clinique\">stable</span>.</li>\n          <li>Conduite par le <span class=\"kw-clinique\">gériatre</span>, souvent aidé d'une équipe : <span class=\"kw-clinique\">IDE</span>, <span class=\"kw-clinique\">assistante sociale</span>, <span class=\"kw-clinique\">ergothérapeute</span>.</li>\n        </ul>\n      </div>\n      <p><strong>Domaines explorés</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fonctions cognitives</span></li>\n        <li><span class=\"kw-clinique\">Autonomie</span></li>\n        <li><span class=\"kw-clinique\">Marche</span> et <span class=\"kw-clinique\">chute</span></li>\n        <li><span class=\"kw-clinique\">État nutritionnel</span></li>\n        <li><span class=\"kw-clinique\">Thymie</span> (dépression)</li>\n        <li><span class=\"kw-clinique\">Confusion</span></li>\n        <li><span class=\"kw-clinique\">Risque d'escarre</span></li>\n        <li><span class=\"kw-etio\">Comorbidités</span> et <span class=\"kw-alerte\">risque iatrogène</span></li>\n      </ul>\n      <p>Le détail des outils par domaine est traité à l'objectif « outils d'évaluation globale du sujet âgé ».</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé · 133 — Autonomie-dépendance du sujet âgé · 250 — Dénutrition</em></p>","frequence":0},{"id":"130-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le modèle du « 1 + 2 + 3 » ou « 1 + 3 » pour la décompensation en gériatrie","contenu":"<p>Le <span class=\"kw-def\"><strong>modèle de décompensation de J.P. Bouchon « 1 + 2 + 3 »</strong></span> explique comment la <span class=\"kw-alerte\">décompensation</span> clinique survient chez la personne âgée : elle apparaît quand <span class=\"kw-clinique\">les</span> facteurs s'<strong>additionnent</strong> (1 + 2 + 3, ou <span class=\"kw-def\">1 + 3</span> en l'absence de maladie chronique).</p>\n      <table >\n        <thead><tr><th>Facteur</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Facteur 1</strong></span><br>Vieillissement physiologique de l'organe</td>\n            <td><span class=\"kw-clinique\">Déclin très progressif</span> de la fonction d'organe. Le <span class=\"kw-alerte\">seuil d'insuffisance d'organe n'est JAMAIS atteint</span> par le seul vieillissement ; l'<strong>âge n'explique pas un symptôme aigu</strong> (ni <span class=\"kw-clinique\">dyspnée</span>, ni chute, ni confusion).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Facteur 2</strong></span><br>Maladie chronique</td>\n            <td>Diminue plus rapidement la <span class=\"kw-clinique\">réserve fonctionnelle</span> → <span class=\"kw-alerte\">vulnérabilité</span> (capacité d'adaptation basse). Peut être <strong>absente</strong> chez le très âgé, d'où le schéma <span class=\"kw-def\">1 + 3</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Facteur 3</strong></span><br>Facteur précipitant</td>\n            <td><span class=\"kw-etio\">Situation aiguë</span> qui rend le patient <span class=\"kw-clinique\">symptomatique</span>. C'est le facteur <strong>le plus accessible à une intervention</strong> et le plus souvent <span class=\"kw-clinique\">réversible</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 123 — Vieillissement normal · 131 — Troubles de la marche et de l'équilibre du sujet âgé</em></p>","frequence":0},{"id":"130-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs précipitants de décompensation","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">facteurs précipitants</span> (facteur 3 du modèle de Bouchon) sont la <strong>cible thérapeutique prioritaire</strong> car les plus souvent réversibles. Liste <em>non exhaustive</em>, classée en 4 catégories.</p>\n      <table >\n        <thead><tr><th>Pathologies aiguës</th><th>Traumatismes physiques</th><th>Iatrogénie</th><th>Traumatismes psychiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-etio\">Infection</span>, <span class=\"kw-etio\">anémie</span>, <span class=\"kw-etio\">globe urinaire</span>, <span class=\"kw-etio\">fécalome</span>, <span class=\"kw-etio\">déshydratation</span>, <span class=\"kw-etio\">dysnatrémie</span>, <span class=\"kw-etio\">hypercalcémie</span>, <span class=\"kw-etio\">hypoglycémie</span>, <span class=\"kw-etio\">thrombose veineuse profonde</span>, <span class=\"kw-etio\">trouble du rythme</span>, <span class=\"kw-etio\">infarctus du myocarde</span>, <span class=\"kw-etio\">AVC</span>\n            </td>\n            <td>\n              <span class=\"kw-etio\">Chutes</span>, <span class=\"kw-etio\">fractures</span>, <span class=\"kw-etio\">canicule</span>\n            </td>\n            <td>\n              <span class=\"kw-alerte\">Introduction d'un nouveau traitement</span>, <span class=\"kw-alerte\">sevrage de traitement</span>, <span class=\"kw-alerte\">modification de posologie</span>\n            </td>\n            <td>\n              <span class=\"kw-etio\">Agression</span>, <span class=\"kw-etio\">maltraitance</span>, <span class=\"kw-etio\">conflit</span>, <span class=\"kw-etio\">deuil</span>, <span class=\"kw-etio\">déménagement</span>, <span class=\"kw-etio\">changement de chambre ou de personnels soignants</span> en institution\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>L'<span class=\"kw-alerte\">iatrogénie</span> est le facteur précipitant le plus accessible à la prévention</strong> — à traquer systématiquement (+++).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span> · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":0},{"id":"130-5","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la cascade gériatrique et du cercle vicieux gériatrique","contenu":"<p>La <span class=\"kw-def\"><strong>cascade gériatrique</strong></span> est un <span class=\"kw-def\">enchaînement d'événements</span> où un <span class=\"kw-etio\">facteur déclenchant</span> décompense une fonction d'organe, ce qui en décompense d'autres de proche en proche (<span class=\"kw-clinique\">pathologies « en cascade »</span>), réalisant un <span class=\"kw-def\">cercle vicieux gériatrique</span> d'aggravations successives.</p>\n      <p>Se rencontre surtout chez <span class=\"kw-clinique\">les</span> patients avec :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Polypathologie</span></li>\n        <li><span class=\"kw-clinique\">Polymédication</span></li>\n        <li><span class=\"kw-clinique\">Dépendance</span> et <span class=\"kw-clinique\">perte d'autonomie</span></li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Exemple concret (fiche source)</strong> — Sujet de <span class=\"kw-chiffre\">95 ans</span> :\n        <ul>\n          <li><span class=\"kw-etio\">Grippe</span> → <span class=\"kw-clinique\">déshydratation</span> majorée par un <span class=\"kw-ttt\">diurétique thiazidique</span> ;</li>\n          <li>→ <span class=\"kw-alerte\">décompensation diabétique hyperosmolaire</span> + <span class=\"kw-clinique\">hypotension orthostatique</span> ;</li>\n          <li>→ <span class=\"kw-alerte\">chute</span> ;</li>\n          <li>→ <span class=\"kw-clinique\">confusion</span> et <span class=\"kw-clinique\">station prolongée au sol</span> → aggravation.</li>\n        </ul>\n      </div>\n      <p><strong>Point clé :</strong> chez un sujet jeune, le même facteur (la <span class=\"kw-etio\">grippe</span>) n'aurait <strong>pas</strong> entraîné cette cascade.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 120 — Complications immobilité - décubitus · 123 — Vieillissement normal</em></p>","frequence":0},{"id":"130-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition du vieillissement pathologique","contenu":"<p>Le <span class=\"kw-def\"><strong>« vieillissement pathologique »</strong></span> est un <strong>abus de langage</strong> qui ne connaît pas de définition précise.</p>\n      <ul>\n        <li>On l'emploie lorsque différentes <span class=\"kw-etio\">pathologies s'ajoutent à l'effet de l'âge</span> et rendent le patient <span class=\"kw-alerte\">vulnérable au moindre événement intercurrent</span>.</li>\n        <li>Il s'oppose au <span class=\"kw-def\">« vieillissement réussi »</span> : <span class=\"kw-clinique\">faible diminution des capacités fonctionnelles</span>, <span class=\"kw-clinique\">réserves conservées</span>.</li>\n        <li>À distinguer du <span class=\"kw-def\">vieillissement physiologique normal</span> qui, seul, <span class=\"kw-alerte\">ne franchit pas le seuil d'insuffisance d'organe</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 123 — Vieillissement normal</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0},{"id":"130-7","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la polypathologie","contenu":"<p>La <span class=\"kw-def\"><strong>polypathologie</strong></span> est la <span class=\"kw-def\">présence simultanée de plusieurs maladies chroniques</span> chez une même personne âgée (<span class=\"kw-chiffre\">5 en moyenne</span>).</p>\n      <ul>\n        <li>Concerne la <strong>majorité des patients de <span class=\"kw-chiffre\">&gt; 80 ans</span></strong>.</li>\n      </ul>\n      <p><strong>Évaluation du poids des <span class=\"kw-def\">comorbidités</span></strong> par des scores :</p>\n      <ul>\n        <li><span class=\"kw-def\">Score de Charlson</span></li>\n        <li><span class=\"kw-def\">CIRS-G</span> (<em>Cumulative Illness Rating Scale-Geriatric</em>) : de <span class=\"kw-chiffre\">1 = absence d'atteinte</span> à <span class=\"kw-chiffre\">4 = atteinte sévère</span> menaçant le <span class=\"kw-def\">pronostic</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 123 — Vieillissement normal · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":0,"liens":[{"href":"http://medicalcul.free.fr/cirs.html","label":"Calculateur CIRS-G"},{"href":"https://www.rdplf.org/calculateurs/pages/charlson/charlson.html","label":"Calculateur score de Charlson"}]},{"id":"130-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les conséquences de la polypathologie sur la démarche diagnostique","contenu":"<p>Chez le sujet âgé <span class=\"kw-clinique\">polypathologique</span>, le motif de consultation n'est souvent <strong>pas</strong> un symptôme directement lié à une pathologie aiguë, mais :</p>\n      <ul>\n        <li>un (ou plusieurs) <span class=\"kw-etio\">facteur(s) déclenchant(s)</span> qui décompense(nt) un ou plusieurs organes ;</li>\n        <li>une <span class=\"kw-clinique\">sémiologie souvent abâtardie</span>, <span class=\"kw-clinique\">manquante</span> ou <span class=\"kw-clinique\">« d'emprunt »</span> ;</li>\n        <li>un <span class=\"kw-alerte\">risque de banalisation</span> : symptômes rattachés à tort au seul vieillissement par le patient et le médecin.</li>\n      </ul>\n      <p><strong>Difficultés d'interprétation</strong></p>\n      <ul>\n        <li>Apparition d'une <span class=\"kw-clinique\">douleur aiguë</span> sur fond de <span class=\"kw-clinique\">douleur chronique</span> ;</li>\n        <li>Survenue d'une <span class=\"kw-clinique\">confusion</span> sur un <span class=\"kw-clinique\">trouble neurocognitif majeur</span> ;</li>\n        <li><span class=\"kw-clinique\">Douleur abdominale nouvelle</span> sur <span class=\"kw-clinique\">constipation chronique</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé · 134 — Bases neurophysiologiques de la douleur</em></p>","frequence":0},{"id":"130-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les spécificités sémiologiques du sujet âgé","contenu":"<p>La <span class=\"kw-def\"><strong>symptomatologie d'emprunt</strong></span> est centrale : un trouble se manifeste par le <span class=\"kw-clinique\">symptôme d'un autre organe</span>, exposant au retard diagnostique.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Spécificité sémiologique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>IDM</strong></span></td><td>Absence de <span class=\"kw-clinique\">douleur</span> dans <span class=\"kw-chiffre\">30 %</span> des cas, même sans <span class=\"kw-etio\">diabète</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Infection</strong></span></td><td><span class=\"kw-clinique\">Fièvre</span> inconstante</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Abdomen chirurgical</strong></span></td><td>Absence de <span class=\"kw-clinique\">contracture</span> ou de <span class=\"kw-clinique\">défense</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Globe urinaire, fécalome, infection</strong></span></td><td><span class=\"kw-alerte\">Confusion</span> souvent <strong>seule manifestation</strong></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Pneumonie</strong></span></td><td><span class=\"kw-clinique\">Ronchi</span> au lieu des <span class=\"kw-clinique\">crépitants</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Déshydratation</strong></span></td><td><span class=\"kw-clinique\">Pli cutané</span> sans valeur → chercher la <span class=\"kw-clinique\">sécheresse des aisselles</span> / <span class=\"kw-clinique\">muqueuses</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 134 — Bases neurophysiologiques de la douleur · 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":0},{"id":"130-10","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la polymédicamentation (Polymédication)","contenu":"<p>La <span class=\"kw-def\"><strong>polymédication</strong></span> (= <span class=\"kw-def\">polymédicamentation</span>) est la <span class=\"kw-def\">consommation quotidienne régulière d'au moins <span class=\"kw-chiffre\">cinq molécules</span> différentes</span> par une personne âgée donnée.</p>\n      <ul>\n        <li>Elle augmente le <span class=\"kw-alerte\">risque iatrogène</span> (effets indésirables <span class=\"kw-etio\">médicamenteux</span>) ;</li>\n        <li>Elle rend indispensable l'<span class=\"kw-ttt\">optimisation</span> et la <span class=\"kw-ttt\">réévaluation régulière de l'ordonnance</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span> · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gériatrie.</em></p>","frequence":0},{"id":"130-11","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la fragilité en gériatrie","contenu":"<p>La <span class=\"kw-def\"><strong>fragilité</strong></span> est un <span class=\"kw-def\">syndrome gériatrique facilement mesurable</span> qui permet d'appréhender de manière plus globale la <span class=\"kw-clinique\">vulnérabilité du sujet âgé</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Conditions d'application</strong>\n        <ul>\n          <li>S'applique en conditions médicales <span class=\"kw-clinique\">STABLES</span>.</li>\n          <li><span class=\"kw-alerte\">PAS au décours d'une pathologie</span>.</li>\n        </ul>\n      </div>\n      <ul>\n        <li>Toutes <span class=\"kw-clinique\">les</span> personnes âgées ne sont <strong>pas</strong> fragiles ; la fragilité peut concerner des <span class=\"kw-clinique\">sujets plus jeunes</span> (proportion de sujets fragiles à <span class=\"kw-chiffre\">65 ans ≈ 15 %</span>).</li>\n      </ul>\n      <p><strong>Conséquences</strong> (déclin fonctionnel, <span class=\"kw-ttt\">réduction</span> multisystémique des réserves) :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">État précurseur de la dépendance fonctionnelle</span> ;</li>\n        <li><span class=\"kw-alerte\">Risque de passage en institution</span> ;</li>\n        <li><span class=\"kw-alerte\">Décès</span>.</li>\n      </ul>\n      <div class=\"obj-callout success\"><strong>Avantage :</strong> la fragilité est <span class=\"kw-clinique\">potentiellement réversible</span> — améliorable par <span class=\"kw-clinique\">nutrition</span>, <span class=\"kw-clinique\">activité physique</span>, <span class=\"kw-clinique\">activité sociale</span> et <span class=\"kw-ttt\">traitements</span>.</div>\n      <div class=\"callout callout-danger\"><strong>Distracteurs d'annales (FAUX) :</strong> la fragilité n'est <strong>PAS</strong> associée au <span class=\"kw-alerte\">risque d'escarre</span>, ni d'<span class=\"kw-alerte\">IDM</span>, ni de <span class=\"kw-alerte\">démence</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 123 — Vieillissement normal · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":2},{"id":"130-12","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'évaluation gériatrique standardisée","contenu":"<p>L'<span class=\"kw-def\"><strong>évaluation gériatrique standardisée (EGS)</strong></span> est une <span class=\"kw-def\">démarche diagnostique multidimensionnelle et standardisée</span> dont la <strong>finalité</strong> est de :</p>\n      <ul>\n        <li>recenser <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">déficiences</span> et les <span class=\"kw-clinique\">capacités</span> du sujet âgé ;</li>\n        <li><span class=\"kw-clinique\">hiérarchiser les problèmes</span> ;</li>\n        <li>élaborer un <span class=\"kw-clinique\">plan de soins personnalisé</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Cadre de réalisation</strong>\n        <ul>\n          <li>Réalisée <span class=\"kw-clinique\">hors situation aiguë</span>, chez un patient <span class=\"kw-clinique\">stable</span> ;</li>\n          <li>Par une <span class=\"kw-clinique\">équipe pluridisciplinaire</span>.</li>\n        </ul>\n      </div>\n      <p>Le détail des outils est traité à l'objectif « outils d'évaluation globale du sujet âgé ».</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":0},{"id":"130-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les outils d'évaluation globale du sujet âgé","contenu":"<p>Outils de l'<span class=\"kw-def\">EGS</span>, classés par domaine évalué.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Outils et seuils</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Fonctions cognitives</strong></span></td>\n            <td><strong><span class=\"kw-def\">MMSE</span> :</strong> <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">/30</span>, <span class=\"kw-def\">dépistage</span> rapide d'une détérioration intellectuelle<br><strong><span class=\"kw-def\">MOCA</span> :</strong> dépistage après <span class=\"kw-clinique\">AVC</span><br><strong><span class=\"kw-def\">BREF</span> :</strong> fonctions exécutives frontales<br><strong>Test des 5 mots de <span class=\"kw-def\">Dubois</span> :</strong> mémoire épisodique à long terme</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Autonomie</strong></span></td>\n            <td><span class=\"kw-def\">ADL</span> (<em>Activities of Daily Living</em>) ; <span class=\"kw-def\">IADL</span> (<em>Instrumental ADL</em>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Chute / marche</strong></span></td>\n            <td><strong>Station unipodale :</strong> positive si <span class=\"kw-chiffre\">&lt; 5 s</span> ou nécessité d'écarter <span class=\"kw-clinique\">les</span> bras<br><strong>Timed up and go test :</strong> positif si <span class=\"kw-chiffre\">&gt; 20 s</span><br><strong>Five times sit-to-stand test :</strong> positif si <span class=\"kw-chiffre\">&gt; 15 s</span><br><strong>Stop walking while talking test</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>État nutritionnel</strong></span></td>\n            <td><strong><span class=\"kw-def\">MNA</span> :</strong> <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">/30</span> — dénutrition <span class=\"kw-chiffre\">&lt; 17</span> ; situation à risque <span class=\"kw-chiffre\">17-23,5</span> ; bon état <span class=\"kw-chiffre\">≥ 24</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Confusion</strong></span></td>\n            <td><span class=\"kw-def\">CAM</span> (<em>Confusion Assessment Method</em>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Dépression</strong></span></td>\n            <td><span class=\"kw-def\">GDS</span> (<em>Geriatric Depression Scale</em>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Risque d'escarre</strong></span></td>\n            <td><span class=\"kw-def\">Norton</span>, <span class=\"kw-def\">Braden</span>, <span class=\"kw-def\">Waterlow</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Comorbidités / iatrogénie</strong></span></td>\n            <td><span class=\"kw-def\">Charlson</span>, <span class=\"kw-def\">CIRS-G</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé · 250 — Dénutrition · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":0},{"id":"130-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les spécificités de la prise en charge en gériatrie","contenu":"<p>Le <span class=\"kw-def\">raisonnement « 1 + 2 + 3 »</span> permet une <strong>intervention structurée et hiérarchisée</strong>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Action</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1.</strong> (facteur 3)</td><td>Recherche et correction du <span class=\"kw-etio\">facteur précipitant</span> = <strong>priorité</strong> (le plus souvent <span class=\"kw-clinique\">réversible</span>)</td></tr>\n          <tr><td><strong>2.</strong> (facteur 2)</td><td>Bilan de la <span class=\"kw-etio\">maladie chronique</span> et <span class=\"kw-def\">réévaluation</span> du <span class=\"kw-ttt\">traitement de fond</span></td></tr>\n          <tr><td><strong>3.</strong> (facteur 1)</td><td>Mesures améliorant <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">conséquences du vieillissement</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Démarche diagnostique associée</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Détection des situations de vulnérabilité</span> ;</li>\n        <li><span class=\"kw-clinique\">Repérage de la polypathologie</span> ;</li>\n        <li>Traque des <span class=\"kw-etio\">facteurs de décompensation</span> (<span class=\"kw-alerte\">iatrogénie</span> +++).</li>\n      </ul>\n      <p>Prise en charge <span class=\"kw-clinique\">globale</span>, <span class=\"kw-clinique\">pluridisciplinaire</span> et <span class=\"kw-clinique\">préventive de la cascade gériatrique</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span> · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":0},{"id":"130-15","rang":"B","rubrique":"Définition","titre":"Connaître les critères de fragilité","contenu":"<p><span class=\"kw-def\"><strong>Critères de fragilité de Fried</strong></span> (au nombre de <span class=\"kw-chiffre\">5</span>) :</p>\n      <table >\n        <thead><tr><th>#</th><th>Critère</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">1</span></td><td><span class=\"kw-clinique\">Perte de poids involontaire</span> dans la dernière année</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span></td><td>Impression subjective de <span class=\"kw-clinique\">fatigue</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span></td><td><span class=\"kw-clinique\">Réduction des activités physiques</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span></td><td>Diminution de la <span class=\"kw-clinique\">force musculaire</span> (<em>hand grip</em>)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">5</span></td><td>Diminution de la <span class=\"kw-clinique\">vitesse de marche</span> (<span class=\"kw-chiffre\">&lt; 0,8 m/s</span> = élément <strong>le plus déterminant</strong>, <span class=\"kw-alerte\">prédit à elle seule la mortalité</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interprétation</strong></p>\n      <table >\n        <thead><tr><th>Statut</th><th>Nombre de critères</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Robuste</span> (non fragile)</td><td><span class=\"kw-chiffre\">0 critère</span></td></tr>\n          <tr><td><span class=\"kw-def\">Préfragile</span></td><td><span class=\"kw-chiffre\">1-2 critères</span></td></tr>\n          <tr><td><span class=\"kw-def\">Fragile</span></td><td><span class=\"kw-chiffre\">≥ 3 critères</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 123 — Vieillissement normal · 131 — Troubles de la marche et de l'équilibre du sujet âgé</em></p>","frequence":2},{"id":"130-16","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître des exemples de spécificités sémiologiques avec l'âge ou de polypathologie","contenu":"<p>Exemples concrets de <span class=\"kw-def\">symptomatologie d'emprunt</span> et de <span class=\"kw-def\">difficultés d'interprétation</span> chez la personne âgée polypathologique.</p>\n      <table >\n        <thead><tr><th>Exemple</th><th>Spécificité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>IDM sans douleur</strong></span></td><td>Absence de <span class=\"kw-clinique\">douleur</span> dans <span class=\"kw-chiffre\">30 %</span> des cas</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Infection sans fièvre</strong></span></td><td><span class=\"kw-clinique\">Fièvre</span> inconstante</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Chute / confusion révélatrices</strong></span></td><td>Révèlent une pathologie aiguë : <span class=\"kw-etio\">globe</span>, <span class=\"kw-etio\">fécalome</span>, <span class=\"kw-etio\">infection</span>, <span class=\"kw-etio\">pneumonie</span>, <span class=\"kw-etio\">déshydratation</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Douleur aiguë sur douleur chronique</strong></span></td><td>Difficulté d'interprétation</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Confusion sur trouble neurocognitif majeur</strong></span></td><td>Difficulté d'interprétation</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Douleur abdominale sur constipation chronique</strong></span></td><td>Difficulté d'interprétation</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">Insister sur le <span class=\"kw-alerte\">risque de banalisation</span> et le <span class=\"kw-alerte\">retard diagnostique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé · 134 — Bases neurophysiologiques de la douleur</em></p>","frequence":1}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"b1be7263140a","n":130,"o":"130-1","u":"Définition","t":"Connaître la prise en charge globale du sujet âgé","q":"Quels sont les membres de l'équipe pluridisciplinaire impliqués dans la prise en charge du sujet âgé ?","a":"<ul><li>Gériatre</li><li>Infirmier(e) Diplômé(e) d'État (IDE)</li><li>Assistant(e) social(e)</li><li>Ergothérapeute</li></ul>"},{"i":"c7fb16aa2d52","n":130,"o":"130-1","u":"Définition","t":"Connaître la prise en charge globale du sujet âgé","q":"Quelle est l'approche globale de la prise en charge du sujet âgé malade ?","a":"<p>La prise en charge du sujet âgé malade repose sur une approche globale et pluridisciplinaire, fondée sur le <strong>raisonnement gériatrique « 1 + 2 + 3 »</strong> et sur l'<strong>évaluation gériatrique standardisée (EGS)</strong>. En amont, elle inclut la détection des situations de vulnérabilité et le repérage de la polypathologie.</p>"},{"i":"d17a8e464679","n":130,"o":"130-1","u":"Définition","t":"Connaître la prise en charge globale du sujet âgé","q":"En quoi consiste le raisonnement gériatrique « 1 + 2 + 3 » dans la prise en charge du sujet âgé malade ?","a":"<ul><li><strong>1. Rechercher et corriger le facteur précipitant</strong> : C'est la priorité, car il est le plus souvent réversible.</li><li><strong>2. Faire le bilan de la maladie chronique et réévaluer le traitement de fond</strong> : Il faut traquer l'<strong>iatrogénie +++</strong>.</li><li><strong>3. Instaurer des mesures améliorant les conséquences du vieillissement</strong>.</li></ul>"},{"i":"11ddeae7fbc4","n":130,"o":"130-10","u":"Définition","t":"Connaître la définition de la polymédicamentation (Polymédication)","q":"Quel est le risque principal associé à la polymédicamentation chez la personne âgée ?","a":"<p>Le risque principal associé à la polymédicamentation chez la personne âgée est l'<strong>augmentation du risque iatrogène</strong>, c'est-à-dire les effets indésirables médicamenteux.</p>"},{"i":"324dcba733c7","n":130,"o":"130-10","u":"Définition","t":"Connaître la définition de la polymédicamentation (Polymédication)","q":"Quelle est la conséquence pratique de la polymédicamentation dans la prise en charge de la personne âgée ?","a":"<p>La polymédicamentation rend indispensable l'<strong>optimisation</strong> et la <strong>réévaluation régulière de l'ordonnance</strong> de la personne âgée.</p>"},{"i":"77b358386744","n":130,"o":"130-10","u":"Définition","t":"Connaître la définition de la polymédicamentation (Polymédication)","q":"Quelle est la définition de la polymédicamentation chez la personne âgée ?","a":"<p>La polymédicamentation chez la personne âgée est définie par la consommation quotidienne régulière d'au moins <strong>cinq molécules différentes</strong>.</p>"},{"i":"634accd43590","n":130,"o":"130-11","u":"Définition","t":"Connaître la définition de la fragilité en gériatrie","q":"Quels sont les conséquences et l'avantage principal de la reconnaissance de la fragilité chez la personne âgée ?","a":"<ul><li>Les conséquences de la fragilité sont le <strong>déclin fonctionnel</strong>, la réduction multisystémique des réserves, un état précurseur de la <strong>dépendance fonctionnelle</strong>, un risque de passage en institution et le décès.</li><li>L'avantage majeur est que la fragilité est <strong>potentiellement réversible</strong> et améliorable principalement par la <strong>nutrition</strong>, l'<strong>activité physique</strong> et l'<strong>activité sociale</strong>.</li></ul>"},{"i":"d961fcd8705c","n":130,"o":"130-11","u":"Définition","t":"Connaître la définition de la fragilité en gériatrie","q":"Quelle est la définition de la fragilité en gériatrie et dans quelles conditions s'applique-t-elle ?","a":"<p>La fragilité est un <strong>syndrome gériatrique</strong> facilement mesurable qui permet d'appréhender de manière plus globale la <strong>vulnérabilité du sujet âgé</strong>. Elle s'applique dans des conditions médicales <strong>STABLES</strong> et non au décours d'une pathologie aiguë.</p>"},{"i":"fdf62ba09a4f","n":130,"o":"130-11","u":"Définition","t":"Connaître la définition de la fragilité en gériatrie","q":"Quelles sont les caractéristiques de la fragilité à ne pas confondre avec d'autres pathologies, et à quel âge peut-elle survenir ?","a":"<ul><li>La fragilité n'est <strong>PAS associée</strong> au risque d'escarre, ni d'infarctus du myocarde (IDM), ni de démence.</li><li>La fragilité peut concerner des sujets plus jeunes, avec environ <strong>15 % des sujets à 65 ans</strong> présentant ce syndrome. Toutes les personnes âgées ne sont pas fragiles.</li></ul>"},{"i":"29df7fb252ab","n":130,"o":"130-12","u":"Définition","t":"Connaître la définition de l'évaluation gériatrique standardisée","q":"Quelle est la définition de l'évaluation gériatrique standardisée (EGS) ?","a":"<p>L'<strong>évaluation gériatrique standardisée (EGS)</strong> est une démarche diagnostique <strong>multidimensionnelle</strong> et <strong>standardisée</strong> dont la finalité est de :</p><ul><li>Recenser les déficiences et les capacités du sujet âgé.</li><li>Hiérarchiser les problèmes.</li><li>Élaborer un plan de soins personnalisé.</li></ul>"},{"i":"deb976bb9245","n":130,"o":"130-12","u":"Définition","t":"Connaître la définition de l'évaluation gériatrique standardisée","q":"Dans quel cadre de réalisation est effectuée l'évaluation gériatrique standardisée (EGS) ?","a":"<p>L'évaluation gériatrique standardisée (EGS) est réalisée :</p><ul><li><strong>Hors situation aiguë</strong>, chez un patient <strong>stable</strong>.</li><li>Par une <strong>équipe pluridisciplinaire</strong>.</li></ul>"},{"i":"ad1bc93914ff","n":130,"o":"130-14","u":"Prise en charge","t":"Connaître les spécificités de la prise en charge en gériatrie","q":"Quelle action correspond à la priorité (facteur 3) dans le raisonnement \"1 + 2 + 3\" en gériatrie ?","a":"<p>La priorité, correspondant au <strong>facteur 3</strong>, est la recherche et la correction du <strong>facteur précipitant</strong>. Il est souvent <strong>réversible</strong> et son identification est cruciale.</p>"},{"i":"b480a62f858a","n":130,"o":"130-14","u":"Prise en charge","t":"Connaître les spécificités de la prise en charge en gériatrie","q":"Comment doit être la prise en charge globale de la personne âgée pour prévenir la cascade gériatrique ?","a":"<p>La prise en charge globale doit être <strong>pluridisciplinaire</strong> et <strong>préventive</strong> pour éviter la cascade gériatrique.</p>"},{"i":"c790a374c7bf","n":130,"o":"130-14","u":"Prise en charge","t":"Connaître les spécificités de la prise en charge en gériatrie","q":"Quel est le principe du raisonnement \"1 + 2 + 3\" dans la prise en charge gériatrique ?","a":"<p>Ce raisonnement structure et hiérarchise l'intervention médicale autour de <strong>trois facteurs</strong> :</p><ul><li><strong>Facteur 3</strong> (priorité) : Recherche et correction du <strong>facteur précipitant</strong> (le plus souvent réversible).</li><li><strong>Facteur 2</strong> : Bilan de la <strong>maladie chronique</strong> et réévaluation du traitement de fond.</li><li><strong>Facteur 1</strong> : Mesures améliorant les <strong>conséquences du vieillissement</strong>.</li></ul>"},{"i":"cf111d831426","n":130,"o":"130-14","u":"Prise en charge","t":"Connaître les spécificités de la prise en charge en gériatrie","q":"Quelles sont les spécificités de la démarche diagnostique associée à la prise en charge en gériatrie ?","a":"<p>La démarche diagnostique en gériatrie vise à :</p><ul><li>Détecter les situations de <strong>vulnérabilité</strong>.</li><li>Repérer la <strong>polypathologie</strong>.</li><li>Traquer les <strong>facteurs de décompensation</strong>, notamment la <strong>iatrogénie</strong>.</li></ul>"},{"i":"1907ea217f26","n":130,"o":"130-5","u":"Définition","t":"Connaître la définition de la cascade gériatrique et du cercle vicieux gériatrique","q":"Dans quel contexte clinique la cascade gériatrique se rencontre-t-elle le plus souvent ?","a":"<p>La cascade gériatrique se rencontre le plus souvent chez les patients âgés présentant :</p><ul><li>Une <strong>polypathologie</strong>.</li><li>Une <strong>polymédication</strong>.</li><li>Une <strong>dépendance</strong> et/ou une <strong>perte d'autonomie</strong>.</li></ul>"},{"i":"603664baf984","n":130,"o":"130-5","u":"Définition","t":"Connaître la définition de la cascade gériatrique et du cercle vicieux gériatrique","q":"Qu'est-ce que la cascade gériatrique ?","a":"<p>La cascade gériatrique est un enchaînement d'événements où un <strong>facteur déclenchant</strong> (par exemple, une grippe) décompense une fonction d'organe, entraînant ensuite la décompensation d'autres fonctions d'organe de proche en proche. Il en résulte des pathologies qui surviennent « en cascade ».</p>"},{"i":"fe774a901b3f","n":130,"o":"130-5","u":"Définition","t":"Connaître la définition de la cascade gériatrique et du cercle vicieux gériatrique","q":"Qu'est-ce que le cercle vicieux gériatrique ?","a":"<p>Le cercle vicieux gériatrique fait référence à l'aboutissement d'une cascade gériatrique, où les décompensations successives mènent à des <strong>aggravations répétées et auto-entretenues</strong>, créant un cycle négatif pour le patient.</p>"},{"i":"0a9a31023bf2","n":130,"o":"130-6","u":"Définition","t":"Connaître la définition du vieillissement pathologique","q":"Comment peut-on définir le concept de « vieillissement pathologique » en gériatrie ?","a":"<p>Il s'agit d'un <strong>abus de langage</strong>. Il décrit une situation où plusieurs <strong>pathologies</strong> s'ajoutent aux effets du vieillissement physiologique, rendant le patient <strong>vulnérable</strong> au moindre événement intercurrent.</p>"},{"i":"641443526518","n":130,"o":"130-6","u":"Définition","t":"Connaître la définition du vieillissement pathologique","q":"En quoi le vieillissement pathologique se différencie-t-il du vieillissement physiologique normal ?","a":"<p>Le vieillissement pathologique est marqué par la survenue de maladies qui altèrent la santé et la fonctionnalité. Le <strong>vieillissement physiologique normal</strong>, seul, ne franchit pas le <strong>seuil d'insuffisance d'organe</strong> et ne rend pas le patient vulnérable au même degré.</p>"},{"i":"81d69fa95e47","n":130,"o":"130-6","u":"Définition","t":"Connaître la définition du vieillissement pathologique","q":"Quelle est la distinction entre le vieillissement pathologique et le « vieillissement réussi » ?","a":"<p>Le vieillissement pathologique est caractérisé par l'ajout de pathologies et une vulnérabilité accrue. Le « vieillissement réussi », en revanche, présente une <strong>faible diminution des capacités fonctionnelles</strong> et des <strong>réserves d'organe conservées</strong>.</p>"},{"i":"39ede2171662","n":130,"o":"130-7","u":"Définition","t":"Connaître la définition de la polypathologie","q":"Quelle est la définition de la polypathologie chez la personne âgée ?","a":"<p>La polypathologie correspond à la présence simultanée de <strong>plusieurs maladies chroniques</strong> chez une même personne âgée.</p>"},{"i":"5fd600f59a91","n":130,"o":"130-7","u":"Définition","t":"Connaître la définition de la polypathologie","q":"Quelle est la prévalence de la polypathologie chez le sujet âgé ?","a":"<p>Elle concerne la <strong>majorité des patients de plus de 80 ans</strong>, avec une moyenne de <strong>5 maladies chroniques</strong> par personne.</p>"},{"i":"6cc2e29e04da","n":130,"o":"130-7","u":"Définition","t":"Connaître la définition de la polypathologie","q":"Quels scores sont utilisés pour évaluer le poids des comorbidités dans le cadre de la polypathologie chez la personne âgée ?","a":"<p>L'évaluation du poids des comorbidités utilise des scores tels que :</p><ul><li>Le <strong>Score de Charlson</strong>.</li><li>Le <strong>CIRS-G</strong> (Cumulative Illness Rating Scale-Geriatric), qui évalue de 1 (absence d'atteinte) à 4 (atteinte sévère menaçant le pronostic).</li></ul>"},{"i":"6a90d8a7b937","n":130,"o":"130-8","u":"Diagnostic positif","t":"Connaître les conséquences de la polypathologie sur la démarche diagnostique","q":"Donnez des exemples de difficultés d'interprétation des symptômes chez la personne âgée polypathologique.","a":"<ul><li>Apparition d'une <strong>douleur aiguë sur fond de douleur chronique</strong>.</li><li>Survenue d'une <strong>confusion sur un trouble neurocognitif majeur</strong> déjà existant.</li><li>Douleur abdominale nouvelle sur une <strong>constipation chronique</strong> habituelle.</li></ul>"},{"i":"6b163087c8a3","n":130,"o":"130-8","u":"Diagnostic positif","t":"Connaître les conséquences de la polypathologie sur la démarche diagnostique","q":"Comment la sémiologie peut-elle se présenter de manière atypique chez la personne âgée polypathologique ?","a":"<p>La sémiologie chez la personne âgée polypathologique est souvent <strong>abâtardie</strong>, <strong>manquante</strong> ou se présente comme une sémiologie « d'emprunt ». Cela rend le diagnostic plus complexe.</p>"},{"i":"990390e4c3dc","n":130,"o":"130-8","u":"Diagnostic positif","t":"Connaître les conséquences de la polypathologie sur la démarche diagnostique","q":"Quelle est la particularité du motif de consultation chez une personne âgée polypathologique, par rapport à une pathologie aiguë isolée ?","a":"<p>Chez une personne âgée polypathologique, le motif de consultation n'est souvent pas un symptôme directement lié à une pathologie aiguë. Il s'agit plutôt d'un ou plusieurs <strong>facteurs déclenchants</strong> qui décompensent un ou plusieurs organes, sur un terrain déjà fragilisé.</p>"},{"i":"bdb6f4e6c4d7","n":130,"o":"130-8","u":"Diagnostic positif","t":"Connaître les conséquences de la polypathologie sur la démarche diagnostique","q":"Quel est le risque lié à l'interprétation des symptômes chez la personne âgée, aussi bien par le patient que par le médecin ?","a":"<p>Il existe un risque de <strong>banalisation des symptômes</strong>, où les signes cliniques sont rattachés à tort au seul processus de vieillissement, aussi bien par le patient que par le médecin, retardant ou biaisant ainsi le diagnostic d'une nouvelle pathologie aiguë.</p>"},{"i":"73dc25046476","n":130,"o":"130-9","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques du sujet âgé","q":"Quelle spécificité sémiologique peut-on observer pour un infarctus du myocarde (IDM) chez la personne âgée ?","a":"<p>Chez la personne âgée, un IDM peut se manifester par une <strong>absence de douleur</strong> dans environ <strong>30% des cas</strong>, y compris chez les patients non diabétiques.</p>"},{"i":"7be41ff67639","n":130,"o":"130-9","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques du sujet âgé","q":"Quel signe cutané n'est pas fiable pour évaluer une déshydratation chez la personne âgée et quel signe doit-on rechercher préférentiellement ?","a":"<p>Le <strong>pli cutané</strong> est <strong>sans valeur</strong> pour évaluer une déshydratation chez la personne âgée. Il faut préférer rechercher la <strong>sécheresse des aisselles ou des muqueuses</strong>.</p>"},{"i":"8b960777635f","n":130,"o":"130-9","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques du sujet âgé","q":"Quelle est la particularité de la présentation clinique d'une infection chez le sujet âgé ?","a":"<p>La <strong>fièvre</strong> est souvent <strong>inconstante</strong> chez le sujet âgé en cas d'infection, ce qui peut rendre le diagnostic plus difficile.</p>"},{"i":"990f37505dfa","n":130,"o":"130-9","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques du sujet âgé","q":"Quelles sont les spécificités sémiologiques d'un abdomen chirurgical chez la personne âgée ?","a":"<p>Chez la personne âgée, un abdomen chirurgical peut se caractériser par l'<strong>absence de contracture</strong> ou de défense, alors que l'on retrouve souvent :</p><ul><li>Un <strong>globe urinaire</strong></li><li>Un <strong>fécalome</strong></li><li>Une <strong>infection</strong></li><li>Une <strong>confusion</strong> qui peut être la seule manifestation.</li></ul>"},{"i":"e7108f607694","n":130,"o":"130-9","u":"Diagnostic positif","t":"Connaître les spécificités sémiologiques du sujet âgé","q":"Comment la présentation d'une pneumonie diffère-t-elle chez la personne âgée par rapport à l'adulte jeune ?","a":"<p>Chez la personne âgée, la pneumonie peut se manifester par des <strong>ronchi</strong> à l'auscultation pulmonaire, plutôt que les crépitants typiquement retrouvés chez l'adulte jeune.</p>"}]};